export const adminAssetsBlueprintsCreate = (
  assetRequest: AssetRequest,
  options?: SecondParameter<typeof customInstance>,
) => {
  const formData = new FormData();
  formData.append("asset_name", assetRequest.asset_name);
  if (assetRequest.asset_type !== undefined) {
    formData.append("asset_type", assetRequest.asset_type);
  }
  if (assetRequest.mime_type !== undefined) {
    formData.append("mime_type", assetRequest.mime_type);
  }
  if (assetRequest.size !== undefined) {
    formData.append("size", assetRequest.size.toString());
  }
  if (assetRequest.checksum !== undefined) {
    formData.append("checksum", assetRequest.checksum);
  }
  if (assetRequest.version !== undefined) {
    formData.append("version", assetRequest.version);
  }
  formData.append("file_url", assetRequest.file_url);
  if (
    assetRequest.thumbnail_url !== undefined &&
    assetRequest.thumbnail_url !== null
  ) {
    formData.append("thumbnail_url", assetRequest.thumbnail_url);
  }
  if (assetRequest.width !== undefined && assetRequest.width !== null) {
    formData.append("width", assetRequest.width.toString());
  }
  if (assetRequest.height !== undefined && assetRequest.height !== null) {
    formData.append("height", assetRequest.height.toString());
  }
  if (assetRequest.alt_text !== undefined) {
    formData.append("alt_text", assetRequest.alt_text);
  }
  if (assetRequest.caption !== undefined) {
    formData.append("caption", assetRequest.caption);
  }
  if (assetRequest.focal_point !== undefined) {
    formData.append("focal_point", assetRequest.focal_point);
  }
  if (assetRequest.tags !== undefined) {
    formData.append("tags", assetRequest.tags);
  }
  if (assetRequest.storage_provider !== undefined) {
    formData.append("storage_provider", assetRequest.storage_provider);
  }
  if (assetRequest.access_level !== undefined) {
    formData.append("access_level", assetRequest.access_level);
  }
  if (
    assetRequest.uploaded_by !== undefined &&
    assetRequest.uploaded_by !== null
  ) {
    formData.append("uploaded_by", assetRequest.uploaded_by);
  }
  if (assetRequest.generated_by !== undefined) {
    formData.append("generated_by", assetRequest.generated_by);
  }
  if (
    assetRequest.expires_at !== undefined &&
    assetRequest.expires_at !== null
  ) {
    formData.append("expires_at", assetRequest.expires_at);
  }

  return customInstance<AdminAssetsBlueprintsCreate201>(
    {
      url: `/api/v1/admin/assets/blueprints/`,
      method: "POST",
      headers: { "Content-Type": "multipart/form-data" },
      data: formData,
    },
    options,
  );
};

